function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Allocator' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with Allocator(n).';
  const good = (v) => Number.isInteger(v) && v >= 1 && v <= 1000;
  if (!good(args[0][0])) return 'n is a whole number from 1 to 1000.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls to allocate and freeMemory.';
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'allocate') {
      if (a.length !== 2 || !good(a[0]) || !good(a[1])) return 'allocate needs size and mID, each from 1 to 1000.';
    } else if (operations[i] === 'freeMemory') {
      if (a.length !== 1 || !good(a[0])) return 'freeMemory needs an mID from 1 to 1000.';
    } else {
      return 'Only allocate and freeMemory can follow the constructor.';
    }
  }
  return null;
}

