class Allocator {
  constructor(n) {
    this.memory = new Array(n).fill(0);
  }

  allocate(size, mID) {
    let run = 0;
    for (let i = 0; i < this.memory.length; i++) {
      if (this.memory[i] === 0) {
        run++;
      } else {
        run = 0;
      }
      if (run === size) {
        const start = i - size + 1;
        for (let j = start; j <= i; j++) {
          this.memory[j] = mID;
        }
        return start;
      }
    }
    return -1;
  }

  freeMemory(mID) {
    let freed = 0;
    for (let i = 0; i < this.memory.length; i++) {
      if (this.memory[i] === mID) {
        this.memory[i] = 0;
        freed++;
      }
    }
    return freed;
  }
}

