class Allocator {
  constructor(n) {
    this.n = n;
    this.blocks = [];
  }
  allocate(size, mID) {
    for (let start = 0; start + size <= this.n; start++) {
      const end = start + size;
      const clash = this.blocks.some(b => b.start < end && start < b.end);
      if (!clash) {
        this.blocks.push({ start, end, mID });
        return start;
      }
    }
    return -1;
  }
  freeMemory(mID) {
    const mine = this.blocks.filter(b => b.mID === mID);
    this.blocks = this.blocks.filter(b => b.mID !== mID);
    return mine.reduce((total, b) => total + (b.end - b.start), 0);
  }
}

