function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.5 ? 1000 : int(50, 1000)) : int(1, 12);
  const calls = large ? 499 : int(1, 15);
  const idCount = large ? (rand() < 0.5 ? int(2, 20) : 1000) : int(1, 4);
  const maxSize = large ? (rand() < 0.5 ? Math.max(1, Math.floor(n / 10)) : Math.min(1000, n + 5)) : Math.min(1000, n + 1);
  const allocRate = 0.5 + rand() * 0.3;
  const operations = ['Allocator'];
  const args = [[n]];
  for (let i = 0; i < calls; i++) {
    if (rand() < allocRate) {
      operations.push('allocate');
      args.push([int(1, maxSize), int(1, idCount)]);
    } else {
      operations.push('freeMemory');
      args.push([int(1, idCount)]);
    }
  }
  return [operations, args];
}
